//! Differential test of the `time` type against PostgreSQL 17: every case in
//! `fixtures/pg17_time_corpus.tsv` (generated by `fixtures/gen_time_corpus.pl`
//! from a real server) must produce exactly the same text or error.

use std::path::PathBuf;

use yuzhu_datetime::{
    Date, DateOrder, DateStyle, DateTimeEnv, DateTimeError, FsZoneSource, Interval, Time,
    Timestamp, TimestampTz, ZoneDb, date_part_time, extract_time, format_float8, parse_datestyle,
    parse_intervalstyle, parse_timezone_setting,
};

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

type Res = Result<String, DateTimeError>;

fn err_text(e: &DateTimeError) -> String {
    format!("ERROR {} {}", e.sqlstate, e.message)
}

fn opt_time(t: Option<Time>) -> String {
    t.map_or_else(|| "NULL".to_owned(), Time::format)
}

fn eval(kind: &str, a: &str, b: &str, env: &DateTimeEnv<'_>) -> Res {
    let ist = env.interval_style;
    let time = |s: &str| Time::parse(s, -1, env);
    let iv = |s: &str| Interval::parse(s, -1, env);
    Ok(match kind {
        "time_in" => time(a)?.format(),
        "time_typmod" => Time::parse(a, b.parse().unwrap(), env)?.format(),
        "time_pl_iv" => time(a)?.add_interval(&iv(b)?)?.format(),
        "time_mi_iv" => time(a)?.sub_interval(&iv(b)?)?.format(),
        "time_mi_time" => {
            let (x, y) = (time(a)?, time(b)?);
            x.sub_time(y).format(ist)
        }
        "time_to_iv" => time(a)?.to_interval().format(ist),
        "iv_to_time" => Time::from_interval(&iv(a)?)?.format(),
        "time_cmp" => {
            let (x, y) = (time(a)?, time(b)?);
            match x.cmp(&y) {
                std::cmp::Ordering::Less => "-1",
                std::cmp::Ordering::Equal => "0",
                std::cmp::Ordering::Greater => "1",
            }
            .to_owned()
        }
        "make_time" => {
            let p: Vec<&str> = a.split(',').map(str::trim).collect();
            let sec = match p[2].trim_end_matches("::float8").trim_matches('\'') {
                "NaN" => f64::NAN,
                "Infinity" => f64::INFINITY,
                "-Infinity" => f64::NEG_INFINITY,
                s => s.parse().unwrap(),
            };
            Time::make(p[0].parse().unwrap(), p[1].parse().unwrap(), sec)?.format()
        }
        "ts_to_time" => opt_time(Timestamp::parse(a, -1, env)?.to_time()),
        "tstz_to_time" => opt_time(TimestampTz::parse(a, -1, env)?.to_time(env.time_zone)?),
        "date_pl_time" => {
            let d = Date::parse(a, env)?;
            d.add_time(time(b)?)?.format(env)?
        }
        "extract_time" => {
            extract_time(b, time(a)?)?.map_or_else(|| "NULL".to_owned(), |n| n.to_string())
        }
        "part_time" => {
            date_part_time(b, time(a)?)?.map_or_else(|| "NULL".to_owned(), format_float8)
        }
        "time_roundtrip" => time(&time(a)?.format())?.format(),
        other => panic!("unknown kind {other}"),
    })
}

#[test]
fn matches_postgresql_17() {
    let text = std::fs::read_to_string(fixtures().join("pg17_time_corpus.tsv")).expect("corpus");
    let zones = ZoneDb::new(Box::new(FsZoneSource::new(fixtures().join("zoneinfo"))));
    let mut total = 0usize;
    let mut failures: Vec<String> = Vec::new();
    for line in text.lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let cols: Vec<&str> = line.split('\t').collect();
        assert_eq!(cols.len(), 7, "bad line: {line}");
        let (kind, tzname, ds, ist, a, b, expected) = (
            cols[0], cols[1], cols[2], cols[3], cols[4], cols[5], cols[6],
        );
        total += 1;
        let tz = parse_timezone_setting(&zones, tzname).expect("zone setting");
        let (date_style, date_order) =
            parse_datestyle(ds, (DateStyle::default(), DateOrder::default())).expect("datestyle");
        let env = DateTimeEnv {
            date_style,
            date_order,
            interval_style: parse_intervalstyle(ist).expect("intervalstyle"),
            time_zone: &tz,
            zones: &zones,
            now: TimestampTz(0),
        };
        let got = match eval(kind, a, b, &env) {
            Ok(s) => s,
            Err(e) => err_text(&e),
        };
        if got != expected {
            failures.push(format!(
                "{kind} [{tzname} | {ds} | {ist}] a={a:?} b={b:?}\n    expected: {expected}\n    got:      {got}"
            ));
        }
    }
    let shown: Vec<&str> = failures.iter().take(80).map(String::as_str).collect();
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from PostgreSQL 17:\n{}",
        failures.len(),
        total,
        shown.join("\n")
    );
    assert!(total > 10_000, "corpus unexpectedly small: {total}");
}
